#include "cps1_core.h"
#include "cps1_cpu68k.h"

/* Core/Src/porting/cps1/cps1_rc_generated.c -- auto-generated by
 * tools/cps1_recompiler/translate.py from s_cpu_test_program below. Runs
 * the SAME program as the interpreter but via emitted C (goto-threaded
 * basic blocks) instead of fetch/decode/execute, so CPS1_ENGINE_RECOMPILER
 * is a genuinely different code path from CPS1_ENGINE_INTERPRETER -- the
 * interpreter-vs-recompiler diff this whole harness exists for is real now,
 * not two copies of the same stub. Regenerate with
 * tools/cps1_recompiler/selftest.sh if s_cpu_test_program ever changes. */
void cps1_rc_translated(cps1_cpu68k_t *regs);

/*
 * TODO(cps1): CPS1_ENGINE_INTERPRETER should become the real 68000+Z80
 * interpreter and PPU renderer; CPS1_ENGINE_RECOMPILER the static
 * recompiler's translated output (docs/CPS1_ULTIMATE_PORTING_PLAN.md
 * technique 1 / tools/cps1_recompiler/translate.py). Until the recompiler
 * exists, both engines drive the identical cps1_cpu68k interpreter, so a
 * passing interpreter-vs-recompiler diff only proves the harness compares
 * correctly -- it proves nothing about emulation correctness. The
 * framebuffer is still a synthetic placeholder (no PPU yet); the CPU state
 * hash below is the first real, observable execution in this core.
 *
 * s_cpu_test_program is hand-assembled 68000 code (no ROM-loading format
 * exists yet -- see docs/CPS1_FEASIBILITY.md section 6):
 *   MOVEQ #10,D0
 *   MOVEQ #0,D1
 *   loop:    ADDQ #3,D1
 *            DBRA D0,loop
 *   RTS
 * Expected end state: D1 = 33 (11 iterations x 3), D0 = 0x0000FFFF (DBcc
 * only touches the low word), halted = 1.
 */
static const uint8_t s_cpu_test_program[] = {
    0x70, 0x0A, /* MOVEQ #10,D0        */
    0x72, 0x00, /* MOVEQ #0,D1         */
    0x56, 0x81, /* loop: ADDQ #3,D1    */
    0x51, 0xC8, /* DBRA D0,loop        */
    0xFF, 0xFC, /* displacement = -4   */
    0x4E, 0x75, /* RTS                 */
};

#define CPS1_CPU_MAX_STEPS_PER_FRAME 64

typedef struct {
    uint16_t fb[CPS1_FB_WIDTH * CPS1_FB_HEIGHT];
    uint32_t frame;
    cps1_cpu68k_t cpu;
} cps1_engine_state_t;

static cps1_engine_state_t s_engine[CPS1_ENGINE_COUNT];

void cps1_core_reset(cps1_engine_kind_t engine)
{
    cps1_engine_state_t *e = &s_engine[engine];
    e->frame = 0;
    for (int i = 0; i < CPS1_FB_WIDTH * CPS1_FB_HEIGHT; i++)
        e->fb[i] = 0;
    cps1_cpu68k_reset(&e->cpu, s_cpu_test_program, sizeof(s_cpu_test_program));
}

void cps1_core_run_frame(cps1_engine_kind_t engine)
{
    cps1_engine_state_t *e = &s_engine[engine];
    e->frame++;

    if (engine == CPS1_ENGINE_RECOMPILER) {
        if (!e->cpu.halted)
            cps1_rc_translated(&e->cpu);
    } else {
        cps1_cpu68k_run(&e->cpu, CPS1_CPU_MAX_STEPS_PER_FRAME);
    }

    /* Deterministic synthetic pattern standing in for a rendered frame: a
     * diagonal RGB565 gradient that shifts one step per frame. TODO(cps1):
     * replace with the real PPU renderer once one exists. */
    for (int y = 0; y < CPS1_FB_HEIGHT; y++) {
        for (int x = 0; x < CPS1_FB_WIDTH; x++) {
            uint32_t v = (uint32_t)x + (uint32_t)y + e->frame;
            uint16_t r5 = (uint16_t)(v & 0x1Fu);
            uint16_t g6 = (uint16_t)((v * 3u) & 0x3Fu);
            uint16_t b5 = (uint16_t)((v * 7u) & 0x1Fu);
            e->fb[y * CPS1_FB_WIDTH + x] = (uint16_t)((r5 << 11) | (g6 << 5) | b5);
        }
    }
}

const uint16_t *cps1_core_get_framebuffer(cps1_engine_kind_t engine)
{
    return s_engine[engine].fb;
}

uint32_t cps1_core_checksum(cps1_engine_kind_t engine)
{
    const uint16_t *fb = s_engine[engine].fb;
    uint32_t h = 2166136261u;
    for (int i = 0; i < CPS1_FB_WIDTH * CPS1_FB_HEIGHT; i++) {
        h ^= fb[i];
        h *= 16777619u;
    }
    return h;
}

uint32_t cps1_core_cpu_state_hash(cps1_engine_kind_t engine)
{
    return cps1_cpu68k_state_hash(&s_engine[engine].cpu);
}

uint32_t cps1_core_cpu_illegal_count(cps1_engine_kind_t engine)
{
    return s_engine[engine].cpu.illegal_count;
}
